static z_t72_t z_t92_repeated(const z_t92_t* self, uint64_t n);
static z_t72_t z_t92_repeated(const z_t92_t* self, uint64_t n) {
    z_t72_t z = {0};
    uint64_t total = self->size * n;
    z.size = total;
    z.capacity = total + 1;
    z.data = (char*)z_xmalloc(z.capacity + 1);
    for (uint64_t i = 0; i < n; i++) {
        memcpy(z.data + i * self->size, self->data, self->size);
    }
    z.data[total] = '\0';
    return z;
}

static z_t72_t z_t92_concat(
    const z_t92_t* self, const z_t92_t* other);
static z_t72_t z_t92_concat(
    const z_t92_t* self, const z_t92_t* other) {
    z_t72_t z = {0};
    uint64_t total = self->size + other->size;
    z.size = total;
    z.capacity = total + 1;
    z.data = (char*)z_xmalloc(z.capacity + 1);
    memcpy(z.data, self->data, self->size);
    memcpy(z.data + self->size, other->data, other->size);
    z.data[total] = '\0';
    return z;
}

static z_t72_t z_t92_toUpperAscii(const z_t92_t* self);
static z_t72_t z_t92_toUpperAscii(const z_t92_t* self) {
    z_t72_t z = {0};
    z.size = self->size;
    z.capacity = self->size + 1;
    z.data = (char*)z_xmalloc(z.capacity + 1);
    for (uint64_t i = 0; i < self->size; i++) {
        unsigned char c = (unsigned char)self->data[i];
        if (c >= 'a' && c <= 'z') c = (unsigned char)(c - ('a' - 'A'));
        z.data[i] = (char)c;
    }
    z.data[self->size] = '\0';
    return z;
}

static uint32_t z_utf8_decode_one(
    const char* data, uint64_t length, uint64_t* i);
static uint32_t z_utf8_decode_one(
    const char* data, uint64_t length, uint64_t* i) {
    uint64_t idx = *i;
    unsigned char b0 = (unsigned char)data[idx];
    if (b0 < 0x80) { *i = idx + 1; return (uint32_t)b0; }
    uint32_t cp;
    uint64_t need;
    if ((b0 & 0xE0) == 0xC0) { cp = b0 & 0x1Fu; need = 1; }
    else if ((b0 & 0xF0) == 0xE0) { cp = b0 & 0x0Fu; need = 2; }
    else if ((b0 & 0xF8) == 0xF0) { cp = b0 & 0x07u; need = 3; }
    else { *i = idx + 1; return 0xFFFDu; }
    if (idx + 1 + need > length) { *i = idx + 1; return 0xFFFDu; }
    for (uint64_t k = 1; k <= need; k++) {
        unsigned char b = (unsigned char)data[idx + k];
        if ((b & 0xC0) != 0x80) { *i = idx + 1; return 0xFFFDu; }
        cp = (cp << 6) | (b & 0x3Fu);
    }
    *i = idx + 1 + need;
    return cp;
}

static uint64_t z_t92_count(const z_t92_t* self);
static uint64_t z_t92_count(const z_t92_t* self) {
    uint64_t i = 0, n = 0;
    while (i < self->size) {
        (void)z_utf8_decode_one(self->data, self->size, &i);
        n++;
    }
    return n;
}

static z_t551_t z_t92_indexOf(const z_t92_t* self, const z_t92_t* needle);
static z_t551_t z_t92_indexOf(const z_t92_t* self, const z_t92_t* needle) {
    z_t551_t out = {0};
    uint64_t r = z_t92_indexOf_raw(self, needle);
    if (r == UINT64_MAX) {
        out.tag = Z_T551_TAG_0;
        return out;
    }
    out.tag = Z_T551_TAG_1;
    out.data.a1 = r;
    return out;
}


static z_t551_t z_t92_lastIndexOf(const z_t92_t* self, const z_t92_t* needle);
static z_t551_t z_t92_lastIndexOf(const z_t92_t* self, const z_t92_t* needle) {
    z_t551_t out = {0};
    if (needle->size == 0) {
        out.tag = Z_T551_TAG_1;
        out.data.a1 = self->size;
        return out;
    }
    if (needle->size > self->size) {
        out.tag = Z_T551_TAG_0;
        return out;
    }
    for (uint64_t i = self->size - needle->size + 1; i > 0; i--) {
        uint64_t idx = i - 1;
        if (memcmp(self->data + idx, needle->data, needle->size) == 0) {
            out.tag = Z_T551_TAG_1;
            out.data.a1 = idx;
            return out;
        }
    }
    out.tag = Z_T551_TAG_0;
    return out;
}


