static const z_t5819_t _zag2100 = { { .data = "create", .size = 6 }, { .length = 2, .data = _zag2099 }, { .data = "static z_@@NAME@@_t z_@@NAME@@_create(uint64_t _capacity);\nstatic z_@@NAME@@_t z_@@NAME@@_create(uint64_t _capacity) {\n    z_@@NAME@@_t _this = {0};\n    if (_capacity > 0) {\n        uint32_t _p2 = 8;\n        while ((uint64_t)z_@@NAME@@_entries_cap(_p2) < _capacity && _p2 < 0x40000000u) {\n            _p2 <<= 1;\n        }\n        _this.capacity = _p2;\n        _this.entries = (z_@@NAME@@_entry_t*)z_xcalloc(\n            z_@@NAME@@_entries_cap(_p2), sizeof(z_@@NAME@@_entry_t));\n        if (_p2 > Z_@@MACRO@@_SMALL_MAX) {\n            _this.indices = (uint32_t*)z_xcalloc(_p2, sizeof(uint32_t));\n        }\n    }\n    return _this;\n}", .size = 629 } };
