static const z_t5819_t _zag2102 = { { .data = "grow", .size = 4 }, { .length = 4, .data = _zag2101 }, { .data = "/* Double the index and re-slot. `entries` is dense and stays in insertion\n   order, so there is nothing to compact -- only the sparse index is rebuilt,\n   and only once it is worth having. */\nstatic void z_@@NAME@@_grow(z_@@NAME@@_t* _this);\nstatic void z_@@NAME@@_grow(z_@@NAME@@_t* _this) {\n    uint32_t _new_cap = _this->capacity == 0 ? 8 : _this->capacity * 2;\n    _this->entries = (z_@@NAME@@_entry_t*)z_xrealloc(_this->entries,\n        (size_t)z_@@NAME@@_entries_cap(_new_cap) * sizeof(z_@@NAME@@_entry_t));\n    _this->capacity = _new_cap;\n    free(_this->indices);\n    _this->indices = NULL;\n    if (_new_cap > Z_@@MACRO@@_SMALL_MAX) {\n        _this->indices = (uint32_t*)z_xcalloc(_new_cap, sizeof(uint32_t));\n        for (uint32_t i = 0; i < _this->length; i++) {\n            uint64_t probe = z_@@NAME@@_slot(_this->entries[i].key) & (_new_cap - 1);\n            while (_this->indices[probe]) probe = (probe + 1) & (_new_cap - 1);\n            _this->indices[probe] = i + 1;\n        }\n    }\n}", .size = 1000 } };
