static const z_t5819_t _zag2104 = { { .data = "find", .size = 4 }, { .length = 1, .data = _zag2103 }, { .data = "/* the entry index for `_key`, or -1. On a miss `_slot_out` (when given, and\n   when an index exists) receives the index slot the key belongs in. */\nstatic int64_t z_@@NAME@@_find(const z_@@NAME@@_t* _this, @@KEY_T@@ _key, uint64_t* _slot_out);\nstatic int64_t z_@@NAME@@_find(const z_@@NAME@@_t* _this, @@KEY_T@@ _key, uint64_t* _slot_out) {\n    if (!_this->indices) {\n        for (uint32_t i = 0; i < _this->length; i++) {\n            if (_this->entries[i].key == _key) return (int64_t)i;\n        }\n        return -1;\n    }\n    uint64_t _mask = _this->capacity - 1;\n    uint64_t probe = z_@@NAME@@_slot(_key) & _mask;\n    for (uint32_t i = 0; i < _this->capacity; i++) {\n        uint32_t slot = _this->indices[probe];\n        if (slot == 0) {\n            if (_slot_out) *_slot_out = probe;\n            return -1;\n        }\n        if (_this->entries[slot - 1].key == _key) {\n            if (_slot_out) *_slot_out = probe;\n            return (int64_t)(slot - 1);\n        }\n        probe = (probe + 1) & _mask;\n    }\n    return -1;\n}", .size = 1032 } };
