static const z_t5819_t _zag2106 = { { .data = "set", .size = 3 }, { .length = 2, .data = _zag2105 }, { .data = "static void z_@@NAME@@_set(z_@@NAME@@_t* _this, @@KEY_T@@ _key, @@VAL_T@@ _val);\nstatic void z_@@NAME@@_set(z_@@NAME@@_t* _this, @@KEY_T@@ _key, @@VAL_T@@ _val) {\n    uint64_t _slot = 0;\n    int64_t existing = z_@@NAME@@_find(_this, _key, &_slot);\n    if (existing >= 0) {\n@@FREE_VAL_DUP@@        _this->entries[existing].value = _val;\n        return;\n    }\n    if ((uint64_t)(_this->length + 1) * 3 >= (uint64_t)_this->capacity * 2) {\n        z_@@NAME@@_grow(_this);\n        /* the index was rebuilt (or has just appeared): re-probe for the slot */\n        z_@@NAME@@_find(_this, _key, &_slot);\n    }\n    uint32_t pos = _this->length;\n    _this->entries[pos].key = _key;\n    _this->entries[pos].value = _val;\n    _this->length++;\n    if (_this->indices) _this->indices[_slot] = pos + 1;\n}", .size = 789 } };
