static const z_t5819_t _zag2121 = { { .data = "", .size = 0 }, { .length = 0, .data = NULL }, { .data = "/* IdMapV.copy -- an owned duplicate that shares no storage with the source.\n   The key is a scalar and the value a valtype, so the dense entry array copies\n   as bytes and the index copies verbatim.\n\n   TWO THINGS THE SIZE MUST COME FROM THE SOURCE, not from `length`. The entry\n   array is allocated at entries_cap(capacity) -- the 2/3 load factor the index\n   grows at -- so a copy sized by length would be reallocated out from under\n   the next `set`. And below SMALL_MAX there is no index at all: `indices ==\n   NULL` is the discriminator every lookup reads, so a copy that allocated one\n   would put the source and the duplicate on different code paths. */\nstatic z_@@NAME@@_t z_@@NAME@@_copy(const z_@@NAME@@_t* _this);\nstatic z_@@NAME@@_t z_@@NAME@@_copy(const z_@@NAME@@_t* _this) {\n    z_@@NAME@@_t _out = {0};\n    if (!_this || _this->capacity == 0) return _out;\n    _out.length = _this->length;\n    _out.capacity = _this->capacity;\n    uint32_t _ecap = z_@@NAME@@_entries_cap(_this->capacity);\n    if (_ecap > 0 && _this->entries) {\n        _out.entries = (z_@@NAME@@_entry_t*)z_xcalloc(_ecap, sizeof(z_@@NAME@@_entry_t));\n        memcpy(_out.entries, _this->entries, (size_t)_ecap * sizeof(z_@@NAME@@_entry_t));\n    }\n    if (_this->indices) {\n        _out.indices = (uint32_t*)z_xcalloc(_this->capacity, sizeof(uint32_t));\n        memcpy(_out.indices, _this->indices, (size_t)_this->capacity * sizeof(uint32_t));\n    }\n    return _out;\n}", .size = 1451 } };
